import { prisma } from "@/lib/db";
import { chat } from "@/lib/ai";
import { estimateTokens, logAiUsage } from "@/lib/usage";
import { DOC_KINDS, type DocKindDef } from "@/lib/constants";

/** Doc kinds whose content depends on tech decisions — regenerated by "align". */
export const STACK_SENSITIVE_KINDS = [
  "TECHNICAL_SPEC",
  "FOLDER_STRUCTURE",
  "RULES",
  "MASTER_PROMPT",
  "BUILD_GUIDE",
] as const;

/**
 * Builds the mandatory stack-lock constraint block injected into every doc
 * prompt so all documents agree on one canonical stack.
 */
export function stackLockBlock(stackLock: string | null | undefined): string {
  if (!stackLock || !stackLock.trim()) return "";
  return `
# CANONICAL TECH STACK (MANDATORY)
The project has LOCKED the following tech stack. Every technology decision in this document MUST use exactly these choices — do not introduce, recommend, or compare alternative frameworks, languages, databases, state libraries, styling systems, or deployment targets. Where the document would normally list options, list only these. Any third-party integration must be compatible with this stack.

"""
${stackLock.trim()}
"""
`;
}

/**
 * Loads the idea and builds the { system, user } messages for a doc kind.
 * Shared by streaming and non-streaming generation.
 */
export async function buildDocMessages(
  ideaId: string,
  kind: string
): Promise<{
  docKind: DocKindDef;
  messages: { role: "system" | "user"; content: string }[];
}> {
  const docKind = DOC_KINDS.find((d) => d.kind === kind);
  if (!docKind) {
    throw new Error(`Unknown document kind: ${kind}`);
  }

  const idea = await prisma.idea.findUnique({
    where: { id: ideaId },
    include: {
      project: { include: { stitchPrompt: true, uploads: true } },
    },
  });
  if (!idea) {
    throw new Error("Idea not found.");
  }
  if (idea.status !== "approved") {
    throw new Error("Approve this idea first (click 'I Like This! ✅').");
  }

  let features: string[] = [];
  try {
    const parsed = JSON.parse(idea.features);
    if (Array.isArray(parsed)) features = parsed.map(String);
  } catch {
    // leave empty
  }

  const sp = idea.project.stitchPrompt;
  const stitchContext = sp
    ? `## Stitch Design Prompt
- App type: ${sp.appType}
- Platform: ${sp.platform}
- Color scheme: ${sp.colorScheme}
- Style: ${sp.style}
- Screens: ${sp.screens}
- Components: ${sp.components}
- Full prompt: ${sp.promptText}`
    : "## Stitch Design Prompt\nNo Stitch prompt generated yet.";

  // Stitch HTML exports are mostly Tailwind/SVG boilerplate — extract a
  // structural outline (headings, buttons, inputs, nav) so the AI sees what
  // each screen actually contains instead of generic filler.
  const stripInline = (s: string): string =>
    s.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();

  const htmlToOutline = (html: string): string => {
    let t = html
      .replace(/<script[\s\S]*?<\/script>/gi, "")
      .replace(/<style[\s\S]*?<\/style>/gi, "")
      .replace(/<svg[\s\S]*?<\/svg>/gi, "");
    t = t.replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, (_, l, c) =>
      `\n${"#".repeat(Number(l))} ${stripInline(c)}\n`);
    t = t.replace(/<button[^>]*>([\s\S]*?)<\/button>/gi, (_, c) =>
      `\n[button: ${stripInline(c)}]\n`);
    t = t.replace(/<input[^>]*placeholder="([^"]*)"[^>]*>/gi, (_, p) =>
      `\n[input: ${p}]\n`);
    t = t.replace(/<input[^>]*>/gi, "\n[input]\n");
    t = t.replace(/<textarea[^>]*placeholder="([^"]*)"[^>]*>/gi, (_, p) =>
      `\n[textarea: ${p}]\n`);
    t = t.replace(/<select[^>]*>([\s\S]*?)<\/select>/gi, (_, c) =>
      `\n[select: ${stripInline(c).slice(0, 120)}]\n`);
    t = t.replace(/<img[^>]*alt="([^"]*)"[^>]*>/gi, (_, a) =>
      `\n[image: ${a}]\n`);
    t = t.replace(/<a[^>]*>([\s\S]*?)<\/a>/gi, (_, c) =>
      ` [link: ${stripInline(c)}] `);
    t = t.replace(/<(nav|header|footer|main)[^>]*>/gi, (_, tag) =>
      `\n[${tag}]\n`);
    t = t.replace(/<[^>]+>/g, " ");
    const lines = t
      .split("\n")
      .map((l) => l.replace(/\s+/g, " ").trim())
      .filter((l) => l.length > 0);
    // Drop lonely fragments that carry no meaning.
    const kept = lines.filter(
      (l) => l.length > 2 || l.startsWith("#") || l.startsWith("[")
    );
    return kept.join("\n");
  };

  const condenseUpload = (u: {
    filename: string;
    type: string;
    content: string | null;
  }): string => {
    if (!u.content) {
      return "(binary screenshot — visual reference only, cannot be read as text)";
    }
    let text = u.content;
    if (u.type === "html") {
      text = htmlToOutline(text);
    } else {
      text = text.replace(/\s+/g, " ").trim();
    }
    const MAX = 4000;
    if (text.length > MAX) text = text.slice(0, MAX) + "… [truncated]";
    return text;
  };

  const uploadContext =
    idea.project.uploads.length === 0
      ? "## Uploaded Stitch Exports\nNone uploaded yet — base the design system on the Stitch prompt above."
      : `## Uploaded Stitch Exports\n${idea.project.uploads
          .map((u) => `### ${u.filename} (${u.type})\n${condenseUpload(u)}`)
          .join("\n\n")}`;

  const platformLine =
    idea.project.platform === "mobile"
      ? "- Target platforms: Android + iOS NATIVE MOBILE APP (this idea came from a Play Store scan). Web is optional, never the primary client."
      : idea.project.platform === "web"
        ? "- Target platforms: Web application."
        : "";

  const context = `# Project Context

## Approved App Idea
- Title: ${idea.title}
- Pitch: ${idea.pitch}
- Key features (CANONICAL — the complete, locked feature list): ${features.join("; ") || "n/a"}
- Target audience: ${idea.targetAudience}
- Monetization: ${idea.monetization ?? "not defined"}
- Category: ${idea.project.category}
${platformLine}
- User preferences: ${idea.project.preferences ?? "none"}
${stackLockBlock(idea.project.stackLock)}
${docKind.skipDesignContext ? "" : `\n${stitchContext}\n\n${uploadContext}`}`;

  const system = `You are a senior technical product manager, software architect, and technical writer. You produce complete, professional, immediately-usable markdown documents for software teams. Use proper markdown: headings, tables, lists, and code blocks where appropriate. Be specific to THIS project — never generic filler. If a canonical tech stack is provided, it is MANDATORY and must be followed exactly with no alternatives. CRITICAL RULE: the Key features list under "Approved App Idea" is the canonical, complete, locked feature list from the start of the project. The Stitch exports define the UI ONLY — they never add, remove, or rename features. If a canonical feature has no corresponding screen or component in the Stitch exports, flag it explicitly as a gap. Never silently drop a feature, and never invent features that are not in the list. PLATFORM RULE: if the context says the target is a native mobile app (Android + iOS), the recommended stack MUST be cross-platform mobile (React Native/Expo or Flutter) — NEVER a web-only frontend (plain React, Next.js web app) as the primary client. Web is optional and secondary for mobile apps. Respond ONLY with the markdown document content, starting with a level-1 heading.`;

  const user = `${context}

# Task
Write the ${docKind.title} (${docKind.label}) for this project.

${docKind.instructions}`;

  return {
    docKind,
    messages: [
      { role: "system", content: system },
      { role: "user", content: user },
    ],
  };
}

/**
 * Saves the document's CURRENT content as a new DocumentVersion before it is
 * overwritten. Version numbers increment per document. Returns the version
 * number created, or null when there was nothing to snapshot (first write).
 */
export async function snapshotDocVersion(
  ideaId: string,
  kind: string
): Promise<number | null> {
  const existing = await prisma.document.findUnique({
    where: { ideaId_kind: { ideaId, kind } },
    include: {
      versions: { orderBy: { version: "desc" }, take: 1, select: { version: true } },
    },
  });
  if (!existing || !existing.content.trim()) return null;
  const nextVersion = (existing.versions[0]?.version ?? 0) + 1;
  await prisma.documentVersion.create({
    data: {
      documentId: existing.id,
      version: nextVersion,
      content: existing.content,
    },
  });
  return nextVersion;
}

/**
 * Generates (or regenerates) one document for an idea, using the project's
 * stack lock as a hard constraint when present. Shared by /api/docs/generate
 * and /api/docs/align.
 *
 * The previous content is snapshotted into DocumentVersion before overwriting,
 * and the NVIDIA call is logged to AiUsage (kind "docgen").
 */
export async function generateDocForIdea(
  ideaId: string,
  kind: string,
  opts: { userId?: string | null } = {}
): Promise<{ id: string; kind: string; content: string; durationMs: number }> {
  const { messages } = await buildDocMessages(ideaId, kind);

  const startedAt = Date.now();
  const content = await chat(messages, { temperature: 0.7, maxTokens: 3500 });
  const durationMs = Date.now() - startedAt;

  // Log usage before touching the DB so a DB hiccup never loses the record.
  const tokensIn = estimateTokens(
    messages.reduce((sum, m) => sum + (m.content?.length ?? 0), 0)
  );
  const tokensOut = estimateTokens(content.length);
  const idea = await prisma.idea.findUnique({
    where: { id: ideaId },
    select: { projectId: true },
  });
  await logAiUsage({
    userId: opts.userId,
    projectId: idea?.projectId ?? null,
    kind: "docgen",
    tokensIn,
    tokensOut,
  });

  // Snapshot the outgoing content so regeneration never loses history.
  await snapshotDocVersion(ideaId, kind);

  const doc = await prisma.document.upsert({
    where: { ideaId_kind: { ideaId, kind } },
    create: { ideaId, kind, content },
    update: { content },
  });

  return { id: doc.id, kind: doc.kind, content: doc.content, durationMs };
}